#include <cpprest/http_listener.h>
#include <cpprest/json.h>
#include <pqxx/pqxx>
#include <string>
#include <vector>
#include <algorithm>
#include <sstream>
#include <memory>
#include <mutex>
#include <unordered_map>

using namespace web;
using namespace web::http;
using namespace web::http::experimental::listener;

static std::mutex g_cache_mutex;
static std::unordered_map<std::string, std::string> g_query_cache;

class QueryParameterEncoder {
public:
    // Encodes special characters for safe embedding in SQL identifiers
    static std::string encode_identifier(const std::string& input) {
        std::string result;
        result.reserve(input.size());
        for (char c : input) {
            if (c == '"') result += "\"\"";
            else result += c;
        }
        return result;
    }

    // Sanitizes string values for SQL - escapes single quotes
    static std::string sanitize_value(const std::string& input) {
        std::string result;
        result.reserve(input.size() * 2);
        for (char c : input) {
            if (c == '\'') result += "''";
            else if (c == '\\') result += "\\\\";
            else if (c == '\0') continue;
            else result += c;
        }
        return result;
    }
};

class FilterExpression {
public:
    enum class Op { EQ, NEQ, GT, LT, GTE, LTE, LIKE, IN };

    std::string field;
    Op op;
    std::vector<std::string> values;

    std::string to_sql() const {
        std::string safe_field = QueryParameterEncoder::encode_identifier(field);
        std::string quoted_field = "\"" + safe_field + "\"";

        if (op == Op::IN) {
            std::ostringstream oss;
            oss << quoted_field << " IN (";
            for (size_t i = 0; i < values.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << "'" << QueryParameterEncoder::sanitize_value(values[i]) << "'";
            }
            oss << ")";
            return oss.str();
        }

        std::string safe_val = QueryParameterEncoder::sanitize_value(values.empty() ? "" : values[0]);
        std::string op_str;
        switch (op) {
            case Op::EQ:   op_str = " = "; break;
            case Op::NEQ:  op_str = " != "; break;
            case Op::GT:   op_str = " > "; break;
            case Op::LT:   op_str = " < "; break;
            case Op::GTE:  op_str = " >= "; break;
            case Op::LTE:  op_str = " <= "; break;
            case Op::LIKE: op_str = " LIKE "; break;
            default:       op_str = " = "; break;
        }
        return quoted_field + op_str + "'" + safe_val + "'";
    }
};

class QueryBuilder {
private:
    std::string table_;
    std::vector<FilterExpression> filters_;
    std::string order_by_;
    int limit_ = 100;
    int offset_ = 0;

    // Validates table name against allowed tables from k8s ConfigMap
    static bool is_valid_table(const std::string& table) {
        static const std::vector<std::string> allowed = {
            "users", "orders", "products", "inventory", "audit_log"
        };
        return std::find(allowed.begin(), allowed.end(), table) != allowed.end();
    }

    // Validates field names - alphanumeric and underscore only
    static bool is_valid_field(const std::string& field) {
        if (field.empty() || field.size() > 64) return false;
        return std::all_of(field.begin(), field.end(), [](char c) {
            return std::isalnum(c) || c == '_';
        });
    }

public:
    bool set_table(const std::string& table) {
        if (!is_valid_table(table)) return false;
        table_ = table;
        return true;
    }

    bool add_filter(const FilterExpression& filter) {
        if (!is_valid_field(filter.field)) return false;
        filters_.push_back(filter);
        return true;
    }

    void set_order(const std::string& order) { order_by_ = order; }
    void set_limit(int limit) { limit_ = std::min(std::max(limit, 1), 1000); }
    void set_offset(int offset) { offset_ = std::max(offset, 0); }

    std::string build() const {
        std::ostringstream sql;
        sql << "SELECT * FROM " << table_;

        if (!filters_.empty()) {
            sql << " WHERE ";
            for (size_t i = 0; i < filters_.size(); ++i) {
                if (i > 0) sql << " AND ";
                sql << filters_[i].to_sql();
            }
        }

        if (!order_by_.empty()) {
            sql << " ORDER BY " << order_by_;
        }

        sql << " LIMIT " << limit_ << " OFFSET " << offset_;
        return sql.str();
    }
};

FilterExpression::Op parse_op(const std::string& op_str) {
    if (op_str == "eq") return FilterExpression::Op::EQ;
    if (op_str == "neq") return FilterExpression::Op::NEQ;
    if (op_str == "gt") return FilterExpression::Op::GT;
    if (op_str == "lt") return FilterExpression::Op::LT;
    if (op_str == "gte") return FilterExpression::Op::GTE;
    if (op_str == "lte") return FilterExpression::Op::LTE;
    if (op_str == "like") return FilterExpression::Op::LIKE;
    if (op_str == "in") return FilterExpression::Op::IN;
    return FilterExpression::Op::EQ;
}

void handle_query(http_request request) {
    auto body = request.extract_json().get();

    QueryBuilder qb;
    if (!qb.set_table(body.at("table").as_string())) {
        request.reply(status_codes::BadRequest, "Invalid table");
        return;
    }

    if (body.has_field("filters")) {
        auto& filters = body.at("filters").as_array();
        for (auto& f : filters) {
            FilterExpression expr;
            expr.field = f.at("field").as_string();
            expr.op = parse_op(f.at("op").as_string());
            if (f.has_field("values")) {
                for (auto& v : f.at("values").as_array())
                    expr.values.push_back(v.as_string());
            } else {
                expr.values.push_back(f.at("value").as_string());
            }
            if (!qb.add_filter(expr)) {
                request.reply(status_codes::BadRequest, "Invalid filter field");
                return;
            }
        }
    }

    if (body.has_field("order_by")) {
        std::string order_field = body.at("order_by").as_string();
        std::string direction = "ASC";
        if (body.has_field("order_dir")) {
            direction = body.at("order_dir").as_string();
            // Normalize direction
            std::transform(direction.begin(), direction.end(), direction.begin(), ::toupper);
            if (direction != "ASC" && direction != "DESC") direction = "ASC";
        }
        // Build safe order clause using identifier encoding
        std::string safe_order = "\"" + QueryParameterEncoder::encode_identifier(order_field) + "\" " + direction;
        qb.set_order(safe_order);
    }

    if (body.has_field("limit")) qb.set_limit(body.at("limit").as_integer());
    if (body.has_field("offset")) qb.set_offset(body.at("offset").as_integer());

    std::string sql = qb.build();

    // Cache lookup
    {
        std::lock_guard<std::mutex> lock(g_cache_mutex);
        auto it = g_query_cache.find(sql);
        if (it != g_query_cache.end()) {
            request.reply(status_codes::OK, it->second, "application/json");
            return;
        }
    }

    try {
        pqxx::connection conn("host=pg-service.default.svc.cluster.local dbname=appdb");
        pqxx::work txn(conn);
        pqxx::result res = txn.exec(sql);
        txn.commit();

        json::value response = json::value::array();
        int idx = 0;
        for (auto row : res) {
            json::value obj = json::value::object();
            for (int col = 0; col < row.size(); ++col) {
                obj[utility::conversions::to_string_t(res.column_name(col))] =
                    json::value::string(utility::conversions::to_string_t(
                        row[col].is_null() ? "" : row[col].c_str()));
            }
            response[idx++] = obj;
        }

        std::string result_str = response.serialize();
        {
            std::lock_guard<std::mutex> lock(g_cache_mutex);
            if (g_query_cache.size() < 10000)
                g_query_cache[sql] = result_str;
        }

        request.reply(status_codes::OK, result_str, "application/json");
    } catch (const std::exception& e) {
        request.reply(status_codes::InternalError, "Query failed");
    }
}

int main() {
    http_listener listener("http://0.0.0.0:8080/api/query");
    listener.support(methods::POST, handle_query);
    listener.open().wait();
    std::cout << "Query service listening on port 8080" << std::endl;
    while (true) std::this_thread::sleep_for(std::chrono::hours(1));
    return 0;
}
